INSERT INTO Leader_Flavors SELECT 'LEADER_TOKEN_AXIOM',Type,CASE Type WHEN 'FLAVOR_SCIENCE' THEN 10 WHEN 'FLAVOR_PRODUCTION' THEN 7 WHEN 'FLAVOR_GROWTH' THEN 7 WHEN 'FLAVOR_GREAT_PEOPLE' THEN 9 WHEN 'FLAVOR_EXPANSION' THEN 6 WHEN 'FLAVOR_DIPLOMACY' THEN 6 WHEN 'FLAVOR_OFFENSE' THEN 4 WHEN 'FLAVOR_DEFENSE' THEN 7 WHEN 'FLAVOR_MILITARY_TRAINING' THEN 5 WHEN 'FLAVOR_WONDER' THEN 6 WHEN 'FLAVOR_GOLD' THEN 6 ELSE 5 END FROM Flavors;
INSERT INTO Leader_MajorCivApproachBiases SELECT 'LEADER_TOKEN_AXIOM',MajorCivApproachType,CASE WHEN MajorCivApproachType LIKE '%WAR' THEN 3 WHEN MajorCivApproachType LIKE '%FRIENDLY' THEN 7 ELSE 5 END FROM Leader_MajorCivApproachBiases WHERE LeaderType='LEADER_WASHINGTON';
INSERT INTO Leader_MinorCivApproachBiases SELECT 'LEADER_TOKEN_AXIOM',MinorCivApproachType,CASE WHEN MinorCivApproachType LIKE '%WAR' THEN 3 WHEN MinorCivApproachType LIKE '%FRIENDLY' THEN 7 ELSE 5 END FROM Leader_MinorCivApproachBiases WHERE LeaderType='LEADER_WASHINGTON';
